use split_decls_genesis :: ourprelude :: * ; use rustc_middle :: mir :: coverage :: { CounterId , CovTerm , ExpressionId } ; #[doc = " Must match the layout of `LLVMRustCounterKind`."] #[derive (Copy , Clone , Debug)] #[repr (C)] pub (crate) enum CounterKind { Zero = 0 , CounterValueReference = 1 , Expression = 2 , } #[doc = " A reference to an instance of an abstract \"counter\" that will yield a value in a coverage"] #[doc = " report. Note that `id` has different interpretations, depending on the `kind`:"] #[doc = "   * For `CounterKind::Zero`, `id` is assumed to be `0`"] #[doc = "   * For `CounterKind::CounterValueReference`,  `id` matches the `counter_id` of the injected"] #[doc = "     instrumentation counter (the `index` argument to the LLVM intrinsic"] #[doc = "     `instrprof.increment()`)"] #[doc = "   * For `CounterKind::Expression`, `id` is the index into the coverage map's array of"] #[doc = "     counter expressions."] #[doc = ""] #[doc = " Corresponds to struct `llvm::coverage::Counter`."] #[doc = ""] #[doc = " Must match the layout of `LLVMRustCounter`."] #[derive (Copy , Clone , Debug)] #[repr (C)] pub (crate) struct Counter { pub (crate) kind : CounterKind , id : u32 , } impl Counter { #[doc = " A `Counter` of kind `Zero`. For this counter kind, the `id` is not used."] pub (crate) const ZERO : Self = Self { kind : CounterKind :: Zero , id : 0 } ; #[doc = " Constructs a new `Counter` of kind `CounterValueReference`."] pub (crate) fn counter_value_reference (counter_id : CounterId) -> Self { Self { kind : CounterKind :: CounterValueReference , id : counter_id . as_u32 () } } #[doc = " Constructs a new `Counter` of kind `Expression`."] pub (crate) fn expression (expression_id : ExpressionId) -> Self { Self { kind : CounterKind :: Expression , id : expression_id . as_u32 () } } pub (crate) fn from_term (term : CovTerm) -> Self { match term { CovTerm :: Zero => Self :: ZERO , CovTerm :: Counter (id) => Self :: counter_value_reference (id) , CovTerm :: Expression (id) => Self :: expression (id) , } } } #[doc = " Corresponds to enum `llvm::coverage::CounterExpression::ExprKind`."] #[doc = ""] #[doc = " Must match the layout of `LLVMRustCounterExprKind`."] #[derive (Copy , Clone , Debug)] #[repr (C)] pub (crate) enum ExprKind { Subtract = 0 , Add = 1 , } #[doc = " Corresponds to struct `llvm::coverage::CounterExpression`."] #[doc = ""] #[doc = " Must match the layout of `LLVMRustCounterExpression`."] #[derive (Copy , Clone , Debug)] #[repr (C)] pub (crate) struct CounterExpression { pub (crate) kind : ExprKind , pub (crate) lhs : Counter , pub (crate) rhs : Counter , } #[doc = " A span of source code coordinates to be embedded in coverage metadata."] #[doc = ""] #[doc = " Must match the layout of `LLVMRustCoverageSpan`."] #[derive (Clone , Debug)] #[repr (C)] pub (crate) struct CoverageSpan { #[doc = " Local index into the function's local-to-global file ID table."] #[doc = " The value at that index is itself an index into the coverage filename"] #[doc = " table in the CGU's `__llvm_covmap` section."] pub (crate) file_id : u32 , #[doc = " 1-based starting line of the source code span."] pub (crate) start_line : u32 , #[doc = " 1-based starting column of the source code span."] pub (crate) start_col : u32 , #[doc = " 1-based ending line of the source code span."] pub (crate) end_line : u32 , #[doc = " 1-based ending column of the source code span. High bit must be unset."] pub (crate) end_col : u32 , } #[doc = " Holds tables of the various region types in one struct."] #[doc = ""] #[doc = " Don't pass this struct across FFI; pass the individual region tables as"] #[doc = " pointer/length pairs instead."] #[doc = ""] #[doc = " Each field name has a `_regions` suffix for improved readability after"] #[doc = " exhaustive destructing, which ensures that all region types are handled."] #[derive (Clone , Debug , Default)] pub (crate) struct Regions { pub (crate) code_regions : Vec < CodeRegion > , pub (crate) expansion_regions : Vec < ExpansionRegion > , pub (crate) branch_regions : Vec < BranchRegion > , } impl Regions { #[doc = " Returns true if none of this structure's tables contain any regions."] pub (crate) fn has_no_regions (& self) -> bool { let Self { code_regions , expansion_regions , branch_regions } = self ; code_regions . is_empty () && expansion_regions . is_empty () && branch_regions . is_empty () } } #[doc = " Must match the layout of `LLVMRustCoverageCodeRegion`."] #[derive (Clone , Debug)] #[repr (C)] pub (crate) struct CodeRegion { pub (crate) cov_span : CoverageSpan , pub (crate) counter : Counter , } #[doc = " Must match the layout of `LLVMRustCoverageExpansionRegion`."] #[derive (Clone , Debug)] #[repr (C)] pub (crate) struct ExpansionRegion { pub (crate) cov_span : CoverageSpan , pub (crate) expanded_file_id : u32 , } #[doc = " Must match the layout of `LLVMRustCoverageBranchRegion`."] #[derive (Clone , Debug)] #[repr (C)] pub (crate) struct BranchRegion { pub (crate) cov_span : CoverageSpan , pub (crate) true_counter : Counter , pub (crate) false_counter : Counter , }